var SPELL_DICT=['the','quick','brown','fox','jumps','over','lazy','dog','hello','world','document','write','editor','code','program','test','build','file','data','system'];
function lev(a,b){var d=[];for(var i=0;i<=a.length;i++){d[i]=[i];}for(var j=1;j<=b.length;j++)d[0][j]=j;
for(var i=1;i<=a.length;i++)for(var j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[a.length][b.length];}
function spellCheck(text){var words=text.toLowerCase().match(/[a-z]+/g)||[];var miss={};
words.forEach(function(w){if(SPELL_DICT.indexOf(w)<0)miss[w]=1;});return Object.keys(miss);}
function spellSuggest(word,n){return SPELL_DICT.map(function(w){return {w:w,d:lev(word.toLowerCase(),w)};}).sort(function(a,b){return a.d-b.d;}).slice(0,n||3).map(function(x){return x.w;});}
